def index_page() -> str:
    return '''<!doctype html><meta charset="utf-8"><title>Synopsis</title><style>
body{font:14px system-ui;margin:0;color:#18212b}header{padding:12px;background:#243447;color:white}.home,.workspace{padding:16px}.workspace{display:grid;grid-template-columns:minmax(220px,1fr) 6px minmax(280px,1fr);height:calc(100vh - 48px);padding:0}.pane{padding:16px;overflow:auto}.map{background:#f2f6f9}.split{background:#b9c5d0;cursor:col-resize}.tabs button{margin-right:4px}.placeholder{border:1px dashed #789;padding:16px;margin-top:10px}li button{margin-left:8px}</style><header>Synopsis · local course library</header><main id="app"></main><script>
const api=(p,o={})=>fetch('/api/'+p,{headers:{'content-type':'application/json'},...o}).then(async r=>{let x=await r.json();if(!r.ok)throw Error(x.error);return x});
let drag=false;document.addEventListener('mousemove',e=>{if(drag){document.querySelector('.workspace').style.gridTemplateColumns=Math.max(180,e.clientX)+'px 6px 1fr'}});document.addEventListener('mouseup',()=>drag=false);
async function home(){let courses=await api('courses');app.innerHTML='<section class=home><h1>Courses</h1><form id=new><input name=title placeholder="Course title" required><button>Create course</button></form><ul>'+courses.map(c=>`<li>${esc(c.title)} <button onclick="openCourse('${c.id}')">Open</button></li>`).join('')+'</ul></section>';new.onsubmit=async e=>{e.preventDefault();let c=await api('courses',{method:'POST',body:JSON.stringify({title:new.title.value})});openCourse(c.id)}}
async function openCourse(id){let s=await api('courses/'+id);app.innerHTML=`<div class=workspace><section class="pane map"><h2>${esc(s.course.title)}</h2><div class=placeholder>Map area — S04 will render CourseRoot, cards and edges here.</div></section><div class=split onmousedown="drag=true"></div><section class=pane><div class=tabs><button>Library</button><button>Open notes</button></div><h2>Notes</h2><input id=q placeholder="Search notes"><label><input id=nc type=checkbox> Without card</label><button id=add>Add note</button><ul id=notes></ul><div class=placeholder>Editor/reader tab host — S03 will own Markdown UI.</div></section></div>`;let render=()=>{let qv=q.value.toLowerCase(), carded=new Set(s.cards.map(c=>c.note_id));notes.innerHTML=s.notes.filter(n=>(!nc.checked||!carded.has(n.id))&&(!qv||n.title.toLowerCase().includes(qv)||n.summary.toLowerCase().includes(qv))).map(n=>`<li>${esc(n.title)} <small>${n.kind}</small></li>`).join('')};q.oninput=nc.onchange=render;render();add.onclick=async()=>{let title=prompt('Note title');if(title){await api('courses/'+id+'/notes',{method:'POST',body:JSON.stringify({title,kind:'concept'})});openCourse(id)}}}
function esc(s){let d=document.createElement('span');d.textContent=s;return d.innerHTML}home();</script>'''
